<?php
namespace Modules\Analytics\Controllers\Web;
use Core\http\ResponseFactory;use Modules\Analytics\Services\SitePageContentService;use RuntimeException;
class SitePageContentController{public function __construct(private SitePageContentService$s){}public function pages(){return$this->run(fn()=>['success'=>true,'data'=>['pages'=>$this->s->pages()]]);}public function content(){return$this->run(fn()=>['success'=>true,'data'=>['items'=>$this->s->content((string)($_GET['page']??''),locale())]]);}public function save(){return$this->run(function(){$this->s->save((int)auth()->id(),$this->payload());return['success'=>true];});}private function payload():array{$raw=base64_decode(strtr((string)request()->input('payload_b64',''),'-_','+/'),true);$d=$raw===false?null:json_decode($raw,true);if(!is_array($d))throw new RuntimeException('اطلاعات محتوا معتبر نیست.');return$d;}private function run(callable$c){try{return ResponseFactory::json($c());}catch(\Throwable$e){return ResponseFactory::json(['success'=>false,'message'=>$e->getMessage()],422);}}}
